# Re-analyze with corrected counts including the missed 4
demo1_in = [
    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 4, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 5, 5, 7, 4, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [4, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 4, 5, 5, 5],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [5, 5, 5, 5, 7, 5, 4, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 4, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 5, 5],
    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 4, 4, 7, 4, 5, 5, 5]
]

print("Finding all 4s:")
four_positions = []
for r in range(len(demo1_in)):
    for c in range(len(demo1_in[r])):
        if demo1_in[r][c] == 4:
            four_positions.append((r, c))
            print(f"  4 at [{r}][{c}]")

print(f"\nTotal 4s: {len(four_positions)}")

# Group by half (above/below row 5)
top_half = [p for p in four_positions if p[0] < 5]
bottom_half = [p for p in four_positions if p[0] > 5]

print(f"\nTop half 4s ({len(top_half)}): {top_half}")
print(f"Bottom half 4s ({len(bottom_half)}): {bottom_half}")

# Check adjacency - look for pairs of 4s in same row
print("\nAdjacent 4s (same row, consecutive columns):")
adjacent_pairs = []
for r in range(len(demo1_in)):
    row_4s = [c for c in range(len(demo1_in[r])) if demo1_in[r][c] == 4]
    for i in range(len(row_4s)):
        for j in range(i+1, len(row_4s)):
            if row_4s[j] - row_4s[i] <= 2:  # Same cell or adjacent/diagonal
                adjacent_pairs.append(((r, row_4s[i]), (r, row_4s[j])))

for p in adjacent_pairs:
    print(f"  {p[0]} and {p[1]}")

# Count 4s by column ranges (based on vertical separators at 4, 9, 14)
regions_top = {"R0": [], "R1": [], "R2": [], "R3": []}
for r in range(5):
    for c in range(len(demo1_in[r])):
        if demo1_in[r][c] == 4:
            if c < 4:
                regions_top["R0"].append((r,c))
            elif c < 9:
                regions_top["R1"].append((r,c))
            elif c < 14:
                regions_top["R2"].append((r,c))
            else:
                regions_top["R3"].append((r,c))

regions_bottom = {"R0": [], "R1": [], "R2": [], "R3": []}
for r in range(6, 11):
    for c in range(len(demo1_in[r])):
        if demo1_in[r][c] == 4:
            if c < 4:
                regions_bottom["R0"].append((r,c))
            elif c < 9:
                regions_bottom["R1"].append((r,c))
            elif c < 14:
                regions_bottom["R2"].append((r,c))
            else:
                regions_bottom["R3"].append((r,c))

print("\nTop regions:")
for k, v in regions_top.items():
    print(f"  {k}: {len(v)} 4s at {v}")

print("\nBottom regions:")
for k, v in regions_bottom.items():
    print(f"  {k}: {len(v)} 4s at {v}")

# Find max region size
max_top = max(regions_top.values(), key=len)
max_bottom = max(regions_bottom.values(), key=len)
print(f"\nMax top region: {max_top}")
print(f"Max bottom region: {max_bottom}")

# Analyze the test input for regions with multiple special values
test_in = [
    [7, 7, 3, 2, 7, 7, 7, 2, 7, 7, 7, 2, 7, 7, 7, 2, 7, 7, 7],
    [7, 7, 7, 2, 7, 3, 7, 2, 7, 3, 7, 2, 7, 3, 7, 2, 7, 3, 3],
    [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2],
    [7, 7, 7, 2, 7, 7, 3, 2, 3, 7, 7, 2, 3, 7, 7, 2, 7, 7, 3],
    [7, 3, 7, 2, 7, 3, 7, 2, 7, 7, 7, 2, 7, 7, 7, 2, 7, 7, 7],
    [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2],
    [7, 3, 7, 2, 7, 7, 7, 2, 3, 7, 7, 2, 7, 3, 7, 2, 7, 7, 7],
    [7, 7, 7, 2, 7, 7, 3, 2, 7, 7, 3, 2, 7, 7, 7, 2, 7, 3, 7]
]

horizontal_seps = [2, 5]  # rows that are all 2s
vertical_seps = [3, 7, 11, 15]  # columns that are all 2s

# Bands: sections between horizontal separators
bands = [[0,1], [3,4], [6,7]]  # Band indices

# Cell columns
cell_col_ranges = [(0,3), (4,7), (8,11), (12,15), (16,19)]

print("Finding special values (3s) in each region:")
region_counts = {}

for bidx, band_rows in enumerate(bands):
    for ccol_idx, (start, end) in enumerate(cell_col_ranges):
        region_cells = []
        for r in band_rows:
            for c in range(start, end):
                if test_in[r][c] == 3:
                    region_cells.append((r, c))
        if region_cells:
            region_counts[(bidx, ccol_idx)] = region_cells

print(f"\nFound {len(region_counts)} regions with 3s:")
for (bidx, ccol_idx), cells in sorted(region_counts.items()):
    print(f"  Region [{bidx}][{ccol_idx}]: {len(cells)} 3s at {cells}")

# Check which regions have multiple adjacent 3s
print("\nChecking adjacency (Manhattan distance <= 1, same band):")
regions_with_adjacent = {}
for (bidx, ccol_idx), cells in region_counts.items():
    has_adjacent = False
    adj_pairs = []
    for i, (r1, c1) in enumerate(cells):
        for j in range(i+1, len(cells)):
            r2, c2 = cells[j]
            if abs(r1 - r2) + abs(c1 - c2) <= 2 and max(abs(r1-r2), abs(c1-c2)) <= 1:
                has_adjacent = True
                adj_pairs.append(((r1,c1), (r2,c2)))
    if has_adjacent:
        regions_with_adjacent[(bidx, ccol_idx)] = adj_pairs

print(f"\nRegions with adjacent pairs:")
for key, pairs in regions_with_adjacent.items():
    print(f"  {key}: {pairs}")

